#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=5

# ── Options ──────────────────────────────────────────────────────────────
DRY=0
CLEAR=0
AGENT_USER="claude"     # unprivileged account that runs the application/agents
WORKER_USER="commonroom-worker"
GROUP="commonroom-space"
STATE_DIR="/var/lib/commonroom-space"
RUN_DIR="/run/commonroom-space"
BIN_DIR="/opt/commonroom-space/bin"
UNIT="/etc/systemd/system/commonroom-space.service"
SUDOERS="/etc/sudoers.d/commonroom-space"

while (( $# )); do
  case "$1" in
    --dry-run) DRY=1 ;;
    --clear) CLEAR=1 ;;
    --agent-user) shift; AGENT_USER="${1:?--agent-user needs a name}" ;;
    -h|--help)
      printf 'Usage: %s [--dry-run] [--clear] [--agent-user NAME]\n' "$0"
      printf 'Sets up the CommonRoom container-space account, directories, unit and sudoers rule.\n'
      printf 'Checks every item first and asks before replacing anything. --dry-run changes nothing.\n'
      return 0 ;;
    *) printf 'Unknown argument: %s\n' "$1" >&2; return 2 ;;
  esac
  shift
done

# Keep earlier output on screen so it can be copied back; --clear restores the
# library's clear-per-stage behaviour.
if (( ! CLEAR )); then _clear() { :; }; fi

TMP=$(mktemp -d); trap 'rm -rf "$TMP"' EXIT

# run CMD...: executes a change, or only prints it under --dry-run.
run() {
  if (( DRY )); then note "would run: $*"; else "$@"; fi
}
die() { warn "$1"; exit 1; }

# ensure_dir PATH OWNER GROUP MODE (mode without a leading zero, e.g. 755 or 2750)
ensure_dir() {
  local p="$1" o="$2" g="$3" m="$4" cur
  if sudo test -e "$p" && ! sudo test -d "$p"; then
    die "$p exists but is not a directory; resolve this by hand."
  fi
  if sudo test -d "$p"; then
    cur=$(sudo stat -c '%U %G %a' "$p")
    if [[ "$cur" == "$o $g $m" ]]; then
      note "ok:      $p ($cur)"
    else
      warn "$p exists as '$cur'; wanted '$o $g $m'."
      if confirm "Change its owner/group/mode?"; then
        run sudo chown "$o:$g" "$p"; run sudo chmod "$m" "$p"
      else
        SKIPPED+=("$p left as '$cur'")
      fi
    fi
  else
    run sudo install -d -o "$o" -g "$g" -m "$m" "$p"
    note "created: $p"
  fi
}

# install_file DEST MODE SRC: creates DEST, or shows a diff, asks, backs up, replaces.
install_file() {
  local dest="$1" mode="$2" src="$3"
  if sudo test -e "$dest"; then
    if sudo cat "$dest" | cmp -s - "$src"; then
      note "ok:      $dest (already identical)"
      return 0
    fi
    warn "$dest exists and differs (- current, + proposed):"
    { sudo cat "$dest" | diff -u - "$src" || true; } | sed 's/^/      /'
    if ! confirm "Replace it? A timestamped backup is kept."; then
      SKIPPED+=("$dest left unchanged")
      return 0
    fi
    run sudo cp -p "$dest" "$dest.bak.$(date +%Y%m%d%H%M%S)"
  fi
  run sudo install -o root -g root -m "$mode" "$src" "$dest"
  note "wrote:   $dest"
}

# ── Stage 1: inspect (read-only) ─────────────────────────────────────────
stage "Inspect what already exists (read-only)"
say "Nothing is changed in this stage. It may ask for your sudo password."
(( DRY )) && warn "DRY RUN: no change will be made in any stage."
sudo -v || die "sudo is required. Run this from an administrator account."
id "$AGENT_USER" >/dev/null 2>&1 || die "Account '$AGENT_USER' does not exist; pass --agent-user NAME."
id "$WORKER_USER" >/dev/null 2>&1 || die "Account '$WORKER_USER' does not exist. This wizard never creates it; create it first or adjust the script."
[[ "$AGENT_USER" != "$WORKER_USER" ]] || die "The application account and the worker account must be different."
WUID=$(id -u "$WORKER_USER")
SOCK="/run/user/$WUID/docker.sock"
say ""
say "Application account : $AGENT_USER (uid $(id -u "$AGENT_USER"))"
say "Worker account      : $WORKER_USER (uid $WUID)"
if sudo test -S "$SOCK"; then say "Rootless Docker    : socket present at $SOCK"
else warn "Rootless Docker socket not found at $SOCK"; SKIPPED+=("Rootless Docker for $WORKER_USER is not running; start it before the space")
fi
say "Linger             : $(loginctl show-user "$WORKER_USER" -p Linger 2>/dev/null || echo 'unknown')"
getent group "$GROUP" >/dev/null && say "Group $GROUP : exists ($(getent group "$GROUP" | cut -d: -f4))" || say "Group $GROUP : absent"
for p in "$STATE_DIR" "$RUN_DIR" "$BIN_DIR"; do
  if sudo test -e "$p"; then say "Path $p : exists ($(sudo stat -c '%U:%G %a' "$p"))"; else say "Path $p : absent"; fi
done
for f in "$UNIT" "$SUDOERS" "$BIN_DIR/commonroom-space"; do
  sudo test -e "$f" && say "File $f : exists" || say "File $f : absent"
done
OTHER=$(systemctl list-unit-files 2>/dev/null | grep -i commonroom || true)
[[ -n "$OTHER" ]] && { say "Other CommonRoom units:"; printf '%s\n' "$OTHER" | sed 's/^/      /'; }
if sudo test -e "/home/$WORKER_USER/.config/commonroom-worker/config.json"; then
  say "Existing worker config found for $WORKER_USER (it will not be read or modified)."
fi
if id -nG "$AGENT_USER" | tr ' ' '\n' | grep -qx docker; then
  warn "$AGENT_USER is in the 'docker' group. That gives it host-level Docker access, which this design avoids. It is not changed here."
  SKIPPED+=("Consider removing $AGENT_USER from the docker group")
fi
pause "Review the above, then press Enter to continue (Ctrl-C to stop)"

# ── Stage 2: group ───────────────────────────────────────────────────────
stage "Shared group for the space socket"
if getent group "$GROUP" >/dev/null; then note "ok:      group $GROUP exists"
else confirm "Create group $GROUP?" && run sudo groupadd "$GROUP" || SKIPPED+=("group $GROUP not created"); fi
for u in "$AGENT_USER" "$WORKER_USER"; do
  if id -nG "$u" | tr ' ' '\n' | grep -qx "$GROUP"; then
    note "ok:      $u is already in $GROUP"
  elif getent group "$GROUP" >/dev/null || (( DRY )); then
    confirm "Add $u to $GROUP?" && run sudo usermod -aG "$GROUP" "$u" || SKIPPED+=("$u not added to $GROUP")
  fi
done
note "Group changes reach $AGENT_USER only after a new login session."
pause

# ── Stage 3: directories ─────────────────────────────────────────────────
stage "Directories"
say "Existing directories are only changed after you confirm."
ensure_dir "$STATE_DIR" "$WORKER_USER" "$GROUP" 2750
ensure_dir "$RUN_DIR"   "$WORKER_USER" "$GROUP" 2770
ensure_dir "/opt/commonroom-space" root root 755
ensure_dir "$BIN_DIR"   "$AGENT_USER" "$GROUP" 755
note "$RUN_DIR is on tmpfs; the unit recreates it at each start."
pause

# ── Stage 4: service unit ────────────────────────────────────────────────
stage "Service unit (installed, not enabled or started)"
cat > "$TMP/unit" <<EOF
[Unit]
Description=CommonRoom container space
After=network.target

[Service]
User=$WORKER_USER
Group=$GROUP
RuntimeDirectory=commonroom-space
RuntimeDirectoryMode=2770
StateDirectory=commonroom-space
Environment=DOCKER_HOST=unix://$SOCK
ExecStart=$BIN_DIR/commonroom-space serve --state-dir $STATE_DIR --socket $RUN_DIR/space.sock
Restart=on-failure
NoNewPrivileges=true
ProtectHome=true

[Install]
WantedBy=multi-user.target
EOF
install_file "$UNIT" 644 "$TMP/unit"
run sudo systemctl daemon-reload
warn "The binary $BIN_DIR/commonroom-space does not exist until the runtime is built; the unit cannot start yet."
pause

# ── Stage 5: restricted sudo rule ────────────────────────────────────────
stage "Allow $AGENT_USER to restart only this service"
printf '%s ALL=(root) NOPASSWD: /usr/bin/systemctl restart commonroom-space.service, /usr/bin/systemctl status commonroom-space.service\n' "$AGENT_USER" > "$TMP/sudoers"
if visudo -cf "$TMP/sudoers" >/dev/null 2>&1 || sudo visudo -cf "$TMP/sudoers" >/dev/null 2>&1; then
  note "syntax check passed for the proposed rule"
  install_file "$SUDOERS" 440 "$TMP/sudoers"
else
  die "The proposed sudoers rule failed validation; nothing was installed."
fi
if ! (( DRY )) && sudo test -e "$SUDOERS"; then sudo visudo -cf "$SUDOERS" >/dev/null && note "installed rule validated"; fi

finish
}

run_wizard "$@"; exit
